      status: 500,
      statusText: "Leaky",
      unhandled: true,
      type: "t",
      instance: "i",
      data: 1,
      body: { x: 1 },
    }).toJSON();
    expect(json).toEqual({ status: 500, title: "Internal Server Error" });
  });

