import type { HTTPError } from "../../error.ts";

/**
 * Build the RFC 9457 problem details object for an error.
 *
 * Unhandled errors only expose `status` and a generic `title` (nothing from the error itself).
 */
export function problemDetails(error: HTTPError): Record<string, unknown> & { status: number } {
  const { status } = error;

  if (error.unhandled) {
    const title = STATUS_PHRASES[status];
    return title ? { title, status } : { status };
  }

  const title = error.statusText ?? STATUS_PHRASES[status];
  const json: Record<string, unknown> = { ...error.body };

  // Standard members are only assigned when defined, so `body` extensions are not erased.
  // Key order: type, title, status, detail, instance, data, extensions.
  const ordered: Record<string, unknown> = {};
  if (error.type !== undefined) ordered.type = error.type;
  if (title !== undefined) ordered.title = title;
  ordered.status = status;
  if (error.message !== title) ordered.detail = error.message;
  if (error.instance !== undefined) ordered.instance = error.instance;
  if (error.data !== undefined) ordered.data = error.data;

  // `body.data` wins over `data`; members defined on the instance win over `body`.
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(ordered)) {
    result[key] = ordered[key];
  }
  for (const key of Object.keys(json)) {
    if (key === "data" || !(key in ordered)) result[key] = json[key];
  }
  return result as Record<string, unknown> & { status: number };
}

// RFC 9110 status phrases
const STATUS_PHRASES: Record<number, string> = {
  100: "Continue",
  101: "Switching Protocols",
  102: "Processing",
  103: "Early Hints",
  200: "OK",
  201: "Created",
  202: "Accepted",
  203: "Non-Authoritative Information",
  204: "No Content",
  205: "Reset Content",
  206: "Partial Content",
  207: "Multi-Status",
  208: "Already Reported",
  226: "IM Used",
  300: "Multiple Choices",
  301: "Moved Permanently",
  302: "Found",
  303: "See Other",
  304: "Not Modified",
  305: "Use Proxy",
  307: "Temporary Redirect",
  308: "Permanent Redirect",
  400: "Bad Request",
  401: "Unauthorized",
  402: "Payment Required",
  403: "Forbidden",
  404: "Not Found",
  405: "Method Not Allowed",
  406: "Not Acceptable",
  407: "Proxy Authentication Required",
  408: "Request Timeout",
  409: "Conflict",
  410: "Gone",
  411: "Length Required",
  412: "Precondition Failed",
  413: "Content Too Large",
  414: "URI Too Long",
  415: "Unsupported Media Type",
  416: "Range Not Satisfiable",
  417: "Expectation Failed",
  418: "I'm a Teapot",
  421: "Misdirected Request",
  422: "Unprocessable Content",
  423: "Locked",
  424: "Failed Dependency",
  425: "Too Early",
  426: "Upgrade Required",
  428: "Precondition Required",
  429: "Too Many Requests",
  431: "Request Header Fields Too Large",
  451: "Unavailable For Legal Reasons",
  500: "Internal Server Error",
  501: "Not Implemented",
  502: "Bad Gateway",
  503: "Service Unavailable",
  504: "Gateway Timeout",
  505: "HTTP Version Not Supported",
  506: "Variant Also Negotiates",
  507: "Insufficient Storage",
  508: "Loop Detected",
  510: "Not Extended",
  511: "Network Authentication Required",
};

