        }),
      );
      // expect(res.status).toBe(200);
      expect(await res.json()).toMatchObject({
        body: { name: "tommy", age: 20 },
        headers: {},
      });
    });

    it("invalid body", async () => {
      const res = await handler.fetch(
        toRequest("/?id=123", {
          method: "POST",
          headers: { "x-token": "abc" },
          body: JSON.stringify({ name: 123 }),
        }),
      );
      expect(await res.json()).toMatchObject({
        status: 400,
        title: "Validation failed",
        data: { issues: [{ expected: "string" }] },
      });
      expect(res.status).toBe(400);
    });

    it("invalid headers", async () => {
      const res = await handler.fetch(
        toRequest("/?id=123", {
          method: "POST",
          body: JSON.stringify({ name: 123 }),
        }),
      );
      expect(await res.json()).toMatchObject({
        status: 400,
        title: "Validation failed",
        data: {
          issues: [{ path: ["x-token"], expected: "string" }],
        },
      });
      expect(res.status).toBe(400);
    });

    it("malformed JSON body", async () => {
      const res = await handler.fetch(
        toRequest("/?id=123", {
          method: "POST",
          headers: { "x-token": "abc" },
          body: "{ not json ",
        }),
      );
      expect(res.status).toBe(400);
      expect(await res.json()).toMatchObject({
        status: 400,
        title: "Bad Request",
        detail: "Invalid JSON body",
      });
    });

    it("invalid query", async () => {
      const res = await handler.fetch(
        toRequest("/?id=", {
          method: "POST",
          headers: { "x-token": "abc" },
          body: JSON.stringify({ name: "tommy" }),
        }),
      );
      expect(await res.json()).toMatchObject({
        status: 400,
        title: "Validation failed",
        data: {
          issues: [
            {
              path: ["id"],
              message: "Too small: expected string to have >=3 characters",
            },
          ],
        },
      });
      expect(res.status).toBe(400);
    });

    describe("custom error messages", () => {
      it("invalid body", async () => {
        const res = await handlerCustomError.fetch(
          toRequest("/?id=123", {
            method: "POST",
            headers: { "x-token": "abc" },
            body: JSON.stringify({ name: 123 }),
          }),
        );
        expect(await res.json()).toMatchObject({
          status: 500,
          title: "Custom Zod body validation error",
          detail: "- Invalid input: expected string, received number",
        });
        expect(res.status).toBe(500);
      });

      it("invalid headers", async () => {
        const res = await handlerCustomError.fetch(
          toRequest("/?id=123", {
            method: "POST",
            body: JSON.stringify({ name: 123 }),
          }),
        );
        expect(await res.json()).toMatchObject({
          status: 500,
          title: "Custom Zod headers validation error",
          detail: "- Missing required header",
        });
        expect(res.status).toBe(500);
      });

      it("invalid query", async () => {
        const res = await handlerCustomError.fetch(
          toRequest("/?id=", {
            method: "POST",
            headers: { "x-token": "abc" },
            body: JSON.stringify({ name: "tommy" }),
          }),
        );
        expect(await res.json()).toMatchObject({
          status: 500,
          statusText: "Custom Zod query validation error",
          message: "- Too small: expected string to have >=3 characters",
        });
        expect(res.status).toBe(500);
      });
    });

    describe("async validation", () => {
      const asyncHandler = defineValidatedHandler({
        validate: {
          body: z.object({
            name: z.string().refine(async (name) => name !== "banned", "Name is banned"),
          }),
          headers: z.object({
            "x-token": z.string().refine(async (token) => token.length >= 3, "Token too short"),
          }),
          query: z.object({
            id: z.string().refine(async (id) => id.length >= 3, "Id too short"),
          }),
        },
        handler: async (event) => {
          return { body: await event.req.json() };
        },
      });

      it("valid request", async () => {
        const res = await asyncHandler.fetch(
          toRequest("/?id=123", {
            method: "POST",
            headers: { "x-token": "abc" },
            body: JSON.stringify({ name: "tommy" }),
          }),
        );
        expect(res.status).toBe(200);
        expect(await res.json()).toMatchObject({ body: { name: "tommy" } });
      });

      it("invalid headers", async () => {
        const res = await asyncHandler.fetch(
          toRequest("/?id=123", {
            method: "POST",
            headers: { "x-token": "ab" },
            body: JSON.stringify({ name: "tommy" }),
          }),
        );
        expect(res.status).toBe(400);
        expect(await res.json()).toMatchObject({
          data: { issues: [{ path: ["x-token"], message: "Token too short" }] },
        });
      });

      it("invalid query", async () => {
        const res = await asyncHandler.fetch(
          toRequest("/?id=1", {
            method: "POST",
            headers: { "x-token": "abc" },
            body: JSON.stringify({ name: "tommy" }),
          }),
        );
        expect(res.status).toBe(400);
        expect(await res.json()).toMatchObject({
          data: { issues: [{ path: ["id"], message: "Id too short" }] },
        });
      });

      it("invalid body", async () => {
        const res = await asyncHandler.fetch(
          toRequest("/?id=123", {
            method: "POST",
            headers: { "x-token": "abc" },
            body: JSON.stringify({ name: "banned" }),
          }),
        );
        expect(res.status).toBe(400);
        expect(await res.json()).toMatchObject({
          data: { issues: [{ path: ["name"], message: "Name is banned" }] },
        });
      });
    });
  });
});

/**
