import type { ValidateFunction, ValidateIssues } from "../src/utils/internal/validate.ts";
import { beforeEach } from "vitest";
import { z } from "zod/v4";
import { readValidatedBody, getValidatedQuery, getValidatedRouterParams } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("validate", (t, { it, describe, expect }) => {
  // Custom validator
  const customValidate: ValidateFunction<{
    invalidKey: never;
    default: string;
    field?: string;
  }> = (data: any) => {
    if (data.invalid) {
      throw new Error("Invalid key");
    }
    data.default = "default";
    return data;
  };
  const customValidateWithoutError: ValidateFunction<{
    invalidKey: never;
    default: string;
    field?: string;
  }> = (data: any) => {
    if (data.invalid) {
      return false;
    }
    data.default = "default";
    return data;
  };

  // Zod validator (example)
  const zodValidate = z.object({
    default: z.string().default("default"),
    field: z.string().optional(),
    invalid: z.never().optional(),
  });

  describe("readValidatedBody", () => {
    beforeEach(() => {
      t.app.post("/custom", async (event) => {
        const data = await readValidatedBody(event, customValidate);
        return data;
      });

      t.app.post("/zod", async (event) => {
        const data = await readValidatedBody(event, zodValidate);
        return data;
      });

      t.app.post("/custom-error", async (event) => {
        const data = await readValidatedBody(event, customValidateWithoutError, {
          onError() {
            return {
              status: 500,
              statusText: "Custom validation error",
            };
          },
        });

        return data;
      });

      t.app.post("/custom-error-zod", async (event) => {
        const data = await readValidatedBody(event, zodValidate, {
          onError: ({ issues }) => ({
            status: 500,
            statusText: "Custom Zod validation error",
            message: summarize(issues),
          }),
        });

        return data;
      });
    });

    describe("custom validator", () => {
      it("Valid JSON", async () => {
        const res = await t.fetch("/custom", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ field: "value" }),
        });
        expect(await res.json()).toEqual({
          field: "value",
          default: "default",
        });
        expect(res.status).toEqual(200);
      });

      it("Validate x-www-form-urlencoded", async () => {
        const res = await t.fetch("/custom", {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: "field=value",
        });
        expect(await res.json()).toEqual({
          field: "value",
          default: "default",
        });
        expect(res.status).toEqual(200);
      });

      it("Invalid JSON", async () => {
        const res = await t.fetch("/custom", {
          method: "POST",
          body: JSON.stringify({ invalid: true }),
        });
        expect(await res.text()).include("Invalid key");
        expect(res.status).toEqual(400);
      });
    });

    describe("zod validator", () => {
      it("Valid multipart form data", async () => {
        t.app.post("/form-data", (event) =>
          readValidatedBody(event, zodValidate, { type: "formData" }),
        );

        const formData = new FormData();
        formData.set("field", "value");
        const res = await t.fetch("/form-data", {
          method: "POST",
          body: formData,
        });

        expect(await res.json()).toEqual({
          field: "value",
          default: "default",
        });
      });

      it("Valid", async () => {
        const res = await t.fetch("/zod", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ field: "value" }),
        });
        expect(await res.json()).toEqual({
          field: "value",
          default: "default",
        });
        expect(res.status).toEqual(200);
      });

      it("Invalid", async () => {
        const res = await t.fetch("/zod", {
          method: "POST",
          body: JSON.stringify({ invalid: true }),
        });
        expect(res.status).toEqual(400);
        expect((await res.json()).data?.issues?.[0]?.code).toEqual("invalid_type");
      });

      it("Caught", async () => {
        const res = await t.fetch("/zod", {
          method: "POST",
          body: JSON.stringify({ invalid: true }),
        });
        expect(res.status).toEqual(400);
        expect(await res.json()).toMatchObject({
          data: {
            message: "Validation failed",
            issues: [
              {
                code: "invalid_type",
              },
            ],
          },
        });
      });
    });

    describe("custom error", () => {
      it("Custom error message", async () => {
        const res = await t.fetch("/custom-error", {
          method: "POST",
          body: JSON.stringify({ invalid: true }),
        });

        expect(res.status).toEqual(500);
        expect(await res.json()).toMatchObject({
          statusText: "Custom validation error",
        });
      });

      it("Custom error with zod", async () => {
        const res = await t.fetch("/custom-error-zod", {
          method: "POST",
          body: JSON.stringify({ invalid: true, field: 2 }),
