      });
    });
  });

  describe("getRouterParams", () => {
    const REGEX_NUMBER_STRING = /^-?(?:\d+(?:\.\d+)?|\.\d+)$/;

    // Custom validator
    const customParamValidate: ValidateFunction<{
      id: number;
    }> = (data: any) => {
      if (!data.id || typeof data.id !== "string" || !REGEX_NUMBER_STRING.test(data.id)) {
