import type { HTTPError } from "../../error.ts";

/**
 * Build the RFC 9457 problem details object for an error.
 *
 * Unhandled errors only expose `status` and a generic `title` (nothing from the error itself).
 */
export function problemDetails(error: HTTPError): Record<string, unknown> & { status: number } {
  const { status } = error;

  if (error.unhandled) {
    const title = STATUS_PHRASES[status];
    return title ? { title, status } : { status };
  }

  const title = error.statusText ?? STATUS_PHRASES[status];

  // Key order: type, title, status, detail, instance, data, extensions.
  // Standard members are only set when defined, so `body` extensions are not erased.
  const standard: Record<string, unknown> = {};
  if (error.type !== undefined) standard.type = error.type;
  if (title !== undefined) standard.title = title;
  standard.status = status;
  if (error.message !== title) standard.detail = error.message;
  if (error.instance !== undefined) standard.instance = error.instance;
  if (error.data !== undefined) standard.data = error.data;
  const result = { ...standard } as Record<string, unknown> & { status: number };

  // Members defined on the instance win over `body`, except `data` (`body.data` wins).
  for (const [key, value] of Object.entries(error.body || {})) {
    if (key === "data" || !(key in standard)) result[key] = value;
  }
  return result;
}

